/* flat.js — the FLAT PATTERN viewer: sewing patterns, plasma profiles, any
 * `*.flat.json` (format "plm.flat/1", generated by tools/flat in the
 * manufacturing workspace).
 *
 * WHY NATIVE AND NOT AN <img src=pattern.svg>: the JSON is the model of record
 * — pieces, cut vs finished outline, notches, seams, the nest — and a picture
 * of it cannot answer "which piece is this, how big, what is it sewn to". The
 * viewer draws the model itself, so hovering a piece tells you all of that,
 * and no foreign SVG is ever injected into the page (every string from the
 * file lands via textContent).
 *
 * The geometry contract is draw.py's in tools/flat: a placement shifts a piece
 * to its cut-bbox origin, rotates it about that bbox (0/90/180/270, CCW), then
 * translates. Change one, change both.
 *
 * Public surface: window.renderFlat(container, doc, { files, height }).
 */
(function () {
  const NS = 'http://www.w3.org/2000/svg';
  const MM_IN = 25.4;
  const LAYERS = [
    ['CUT', 'Cut line'], ['SEW', 'Sew line'], ['NOTCH', 'Notches'],
    ['MARK', 'Marks'], ['GRAIN', 'Grain'], ['TEXT', 'Labels'], ['GRID', 'Grid'],
  ];
  const svgEl = (tag, attrs = {}) => {
    const n = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
    return n;
  };
  const h = (tag, cls, text) => {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  };

  function bbox(pts) {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const [x, y] of pts) {
      if (x < x0) x0 = x; if (y < y0) y0 = y; if (x > x1) x1 = x; if (y > y1) y1 = y;
    }
    return [x0, y0, x1 - x0, y1 - y0];
  }
  // draw.py transform(): same maths, same order.
  function placer(piece, rot, dx, dy) {
    const [x0, y0, w, hh] = bbox(piece.cut);
    const r = ((rot % 360) + 360) % 360;
    return (pts) => pts.map(([x, y]) => {
      let lx = x - x0, ly = y - y0, px, py;
      if (r === 0) { px = lx; py = ly; }
      else if (r === 180) { px = w - lx; py = hh - ly; }
      else if (r === 90) { px = hh - ly; py = lx; }
      else { px = ly; py = w - lx; }
      return [px + dx, py + dy];
    });
  }
  // Model space is y-up (CAD); SVG is y-down. Flip at the last moment.
  const pstr = (pts) => pts.map(([x, y]) => `${x.toFixed(2)},${(-y).toFixed(2)}`).join(' ');

  function fmtLen(mm, units) {
    return units === 'in' ? `${(mm / MM_IN).toFixed(2)} in` : `${mm.toFixed(0)} mm`;
  }

  function piecesRow(doc, gap = 60) {
    let x = 0, hmax = 0;
    const out = [];
    for (const p of doc.pieces) {
      const [, , w, hh] = bbox(p.cut);
      out.push({ piece: p.id, copy: 1, x, y: 0, rot: 0 });
      x += w + gap; hmax = Math.max(hmax, hh);
    }
    return { placements: out, w: Math.max(0, x - gap), h: hmax };
  }

  window.renderFlat = function renderFlat(host, doc, opts = {}) {
    host.innerHTML = '';
    host.classList.add('flatv');
    if (!doc || doc.format !== 'plm.flat/1') {
      host.appendChild(h('div', 'flatnote', 'Not a plm.flat/1 document — cannot draw it.'));
      return;
    }
    const byId = Object.fromEntries(doc.pieces.map(p => [p.id, p]));
    const hasNest = !!(doc.nest && (doc.nest.placements || []).length);
    const state = {
      mode: hasNest ? 'nest' : 'pieces',
      units: doc.params && doc.params.spec && doc.params.spec.units === 'mm' ? 'mm' : 'in',
      on: { CUT: true, SEW: true, NOTCH: true, MARK: true, GRAIN: true, TEXT: true, GRID: true },
      vb: null,
    };

    // ---- toolbar ------------------------------------------------------------
    const bar = h('div', 'flatbar');
    const seg = (items, get, set) => {
      const g = h('span', 'flatseg');
      for (const [k, label] of items) {
        const b = h('button', 'btn' + (get() === k ? ' on' : ''), label);
        b.onclick = () => { set(k); g.querySelectorAll('button').forEach(x => x.classList.remove('on')); b.classList.add('on'); };
        g.appendChild(b);
      }
      return g;
    };
    const modes = [['pieces', 'Pieces']];
    if (hasNest) modes.unshift(['nest', 'Cutting layout']);
    bar.appendChild(seg(modes, () => state.mode, (k) => { state.mode = k; state.vb = null; draw(); }));
    bar.appendChild(seg([['in', 'in'], ['mm', 'mm']], () => state.units, (k) => { state.units = k; draw(); side(); }));
    const layers = h('span', 'flatlayers');
    for (const [k, label] of LAYERS) {
      if (k === 'SEW' && doc.process !== 'sew') continue;
      const lab = h('label');
      const cb = h('input'); cb.type = 'checkbox'; cb.checked = state.on[k];
      cb.onchange = () => { state.on[k] = cb.checked; applyLayers(); };
      lab.append(cb, document.createTextNode(' ' + label));
      layers.appendChild(lab);
    }
    bar.appendChild(layers);
    const fit = h('button', 'btn', 'Fit');
    fit.onclick = () => { state.vb = null; draw(); };
    bar.appendChild(fit);
    if (opts.onFull) {
      const full = h('button', 'btn', 'Full screen');
      full.onclick = opts.onFull;
      bar.appendChild(full);
    }
    host.appendChild(bar);

    const warn = (doc.warnings || []);
    for (const w of warn) host.appendChild(h('div', 'flatwarn', '⚠ ' + w));

    // ---- canvas + side panel ------------------------------------------------
    const body = h('div', 'flatbody');
    const stage = h('div', 'flatstage');
    if (opts.height) stage.style.height = opts.height;
    const svg = svgEl('svg', { class: 'flatsvg' });
    stage.appendChild(svg);
    const info = h('div', 'flatinfo', 'Hover a piece.');
    stage.appendChild(info);
    const scale = h('div', 'flatscale');
    stage.appendChild(scale);
    const panel = h('div', 'flatside');
    body.append(stage, panel);
    host.appendChild(body);

    function layout() {
      if (state.mode === 'nest' && hasNest) {
        return { placements: doc.nest.placements, w: doc.nest.stock_width, h: doc.nest.length, stock: true };
      }
      return piecesRow(doc);
    }

    function applyLayers() {
      for (const [k] of LAYERS) {
        svg.querySelectorAll(`[data-layer="${k}"]`).forEach(n => {
          n.style.display = state.on[k] ? '' : 'none';
        });
      }
    }

    function draw() {
      svg.innerHTML = '';
      const L = layout();
      const pad = Math.max(L.w, L.h) * 0.04 + 20;
      const vb0 = [-pad, -L.h - pad, L.w + 2 * pad, L.h + 2 * pad];
      if (!state.vb) state.vb = vb0.slice();
      svg.setAttribute('viewBox', state.vb.join(' '));

      // cutting-mat grid: 1 in (or 50 mm) squares, heavier every 6 in / 250 mm
      const step = state.units === 'in' ? MM_IN : 50;
      const major = state.units === 'in' ? MM_IN * 6 : 250;
      const defs = svgEl('defs');
      const uid = 'fg' + Math.random().toString(36).slice(2, 8);
      const pat = svgEl('pattern', { id: uid, width: step, height: step, patternUnits: 'userSpaceOnUse', x: 0, y: 0 });
      pat.appendChild(svgEl('path', { d: `M ${step} 0 L 0 0 0 ${step}`, class: 'fgrid', 'vector-effect': 'non-scaling-stroke' }));
      const pat2 = svgEl('pattern', { id: uid + 'M', width: major, height: major, patternUnits: 'userSpaceOnUse', x: 0, y: 0 });
      pat2.appendChild(svgEl('path', { d: `M ${major} 0 L 0 0 0 ${major}`, class: 'fgrid2', 'vector-effect': 'non-scaling-stroke' }));
      defs.append(pat, pat2);
      svg.appendChild(defs);
      const big = Math.max(L.w, L.h) * 6;
      const gx = -big, gy = -L.h - big, gw = L.w + 2 * big, gh = L.h + 2 * big;
      const grid = svgEl('g', { 'data-layer': 'GRID' });
      grid.appendChild(svgEl('rect', { x: gx, y: gy, width: gw, height: gh, fill: `url(#${uid})` }));
      grid.appendChild(svgEl('rect', { x: gx, y: gy, width: gw, height: gh, fill: `url(#${uid}M)` }));
      svg.appendChild(grid);

      if (L.stock) {
        const n = doc.nest;
        svg.appendChild(svgEl('rect', { x: 0, y: -n.length, width: n.stock_width, height: n.length, class: 'fstock', 'vector-effect': 'non-scaling-stroke' }));
        if (n.selvage) for (const x of [n.selvage, n.stock_width - n.selvage]) {
          svg.appendChild(svgEl('line', { x1: x, y1: 0, x2: x, y2: -n.length, class: 'fselv', 'vector-effect': 'non-scaling-stroke' }));
        }
        const dfs = Math.max(L.w, L.h) / 70;
        const t = svgEl('text', { x: n.stock_width / 2, y: dfs * 1.6, class: 'fdim', 'text-anchor': 'middle', 'font-size': dfs });
        t.textContent = `${n.stock} — ${fmtLen(n.stock_width, state.units)} wide`;
        const t2 = svgEl('text', { x: n.stock_width + dfs, y: -n.length / 2, class: 'fdim', 'font-size': dfs, transform: `rotate(90 ${n.stock_width + dfs} ${-n.length / 2})`, 'text-anchor': 'middle' });
        t2.textContent = `${fmtLen(n.length, state.units)} of roll · ${n.yards.toFixed(2)} yd`;
        svg.append(t, t2);
      }

      for (const pl of L.placements) {
        const p = byId[pl.piece];
        if (!p) continue;
        const f = placer(p, pl.rot, pl.x, pl.y);
        const g = svgEl('g', { class: 'fpiece' });
        const cut = svgEl('polygon', { points: pstr(f(p.cut)), class: 'fcut', 'data-layer': 'CUT', 'vector-effect': 'non-scaling-stroke' });
        g.appendChild(cut);
        if (doc.process === 'sew') {
          g.appendChild(svgEl('polygon', { points: pstr(f(p.finished)), class: 'fsew', 'data-layer': 'SEW', 'vector-effect': 'non-scaling-stroke' }));
        }
        for (const hole of p.holes_cut || []) {
          g.appendChild(svgEl('polygon', { points: pstr(f(hole)), class: 'fhole', 'data-layer': 'CUT', 'vector-effect': 'non-scaling-stroke' }));
        }
        for (const m of p.marks || []) {
          if (m.kind === 'notch') {
            g.appendChild(svgEl('polyline', { points: pstr(f(m.pts)), class: 'fnotch', 'data-layer': 'NOTCH', 'vector-effect': 'non-scaling-stroke' }));
          } else if (m.kind === 'box') {
            const [[ax, ay], [bx, by]] = m.pts;
            const n = svgEl('polygon', { points: pstr(f([[ax, ay], [bx, ay], [bx, by], [ax, by]])), class: 'fmark', 'data-layer': 'MARK', 'vector-effect': 'non-scaling-stroke' });
            const tt = svgEl('title'); tt.textContent = m.label || 'mark'; n.appendChild(tt);
            g.appendChild(n);
          } else {
            const closed = m.kind === 'grommet' || m.kind === 'hole';
            const n = svgEl(closed ? 'polygon' : 'polyline', { points: pstr(f(m.pts)), class: 'fmark', 'data-layer': 'MARK', 'vector-effect': 'non-scaling-stroke' });
            const tt = svgEl('title'); tt.textContent = m.label || m.kind; n.appendChild(tt);
            g.appendChild(n);
          }
        }
        if ((p.grain || []).length === 2) {
          const [[ax, ay], [bx, by]] = f(p.grain);
          const gl = svgEl('g', { 'data-layer': 'GRAIN', class: 'fgrain' });
          gl.appendChild(svgEl('line', { x1: ax, y1: -ay, x2: bx, y2: -by, 'vector-effect': 'non-scaling-stroke' }));
          const len = Math.hypot(bx - ax, by - ay) || 1, ux = (bx - ax) / len, uy = (by - ay) / len;
          const hs = Math.min(10, len / 4);
          for (const [px, py, s] of [[bx, by, 1], [ax, ay, -1]]) {
            const head = [[px - s * ux * hs - uy * hs / 2, py - s * uy * hs + ux * hs / 2], [px, py],
                          [px - s * ux * hs + uy * hs / 2, py - s * uy * hs - ux * hs / 2]];
            gl.appendChild(svgEl('polyline', { points: pstr(head), 'vector-effect': 'non-scaling-stroke' }));
          }
          g.appendChild(gl);
        }
        // label: name + qty, sized to the piece so small pieces stay legible
        const [lx, ly] = f([p.label_at])[0];
        const [, , pw, ph] = bbox(f(p.cut));
        const fs = Math.max(6, Math.min(60, Math.min(pw, ph) / 8));
        const tx = svgEl('text', { x: lx, y: -ly, class: 'flabel', 'data-layer': 'TEXT', 'text-anchor': 'middle', 'font-size': fs });
        tx.textContent = p.name;
        const tq = svgEl('tspan', { x: lx, dy: fs * 1.2, 'font-size': fs * 0.75 });
        tq.textContent = `cut ${p.qty}` + (L.stock && p.qty > 1 ? ` (#${pl.copy})` : '');
        tx.appendChild(tq);
        g.appendChild(tx);
        g.onmouseenter = () => { g.classList.add('hot'); showPiece(p); };
        g.onmouseleave = () => { g.classList.remove('hot'); };
        svg.appendChild(g);
      }
      applyLayers();
      drawScale();
    }

    function showPiece(p) {
      const u = state.units;
      const [, , w, hh] = bbox(p.cut);
      const [, , fw, fh] = bbox(p.finished);
      info.innerHTML = '';
      info.appendChild(h('b', null, p.name));
      if (p.part && p.part.number) info.appendChild(h('div', null, `part ${p.part.number} v${p.part.version}`));
      info.appendChild(h('div', null, `cut ${p.qty} · ${p.stock || ''}`));
      info.appendChild(h('div', null, `cut size ${fmtLen(w, u)} × ${fmtLen(hh, u)}`));
      if (doc.process === 'sew') info.appendChild(h('div', null, `finished ${fmtLen(fw, u)} × ${fmtLen(fh, u)}`));
      for (const e of p.edges || []) {
        if (!(e.mates || []).length) continue;
        info.appendChild(h('div', 'dim', `${e.id} ${fmtLen(e.length, u)} → ${e.mates.join(' + ')}`));
      }
      if (p.note) info.appendChild(h('div', 'dim', p.note));
    }

    function drawScale() {
      // A ruler that stays true as you zoom: pick a round length ~ 1/5 of view.
      const r = svg.getBoundingClientRect();
      if (!r.width) return;
      const mmPerPx = state.vb[2] / r.width;
      const unit = state.units === 'in' ? MM_IN : 10;
      const nice = [1, 2, 3, 6, 12, 24, 36, 60].map(n => n * unit);
      let len = nice[0];
      for (const n of nice) if (n / mmPerPx <= r.width / 4) len = n;
      scale.style.width = (len / mmPerPx) + 'px';
      scale.textContent = state.units === 'in' ? `${Math.round(len / MM_IN)} in` : `${Math.round(len / 10)} cm`;
    }

    // ---- pan / zoom on the viewBox ----------------------------------------------
    svg.addEventListener('wheel', (e) => {
      e.preventDefault();
      const r = svg.getBoundingClientRect();
      const [vx, vy, vw, vh] = state.vb;
      const k = e.deltaY > 0 ? 1.15 : 1 / 1.15;
      // Keep the point under the cursor fixed (preserveAspectRatio is xMidYMid
      // meet, so work in the rendered scale).
      const s = Math.max(vw / r.width, vh / r.height);
      const ox = (r.width - vw / s) / 2, oy = (r.height - vh / s) / 2;
      const mx = vx + (e.clientX - r.left - ox) * s, my = vy + (e.clientY - r.top - oy) * s;
      state.vb = [mx - (mx - vx) * k, my - (my - vy) * k, vw * k, vh * k];
      svg.setAttribute('viewBox', state.vb.join(' '));
      drawScale();
    }, { passive: false });
    let drag = null;
    svg.addEventListener('pointerdown', (e) => { drag = [e.clientX, e.clientY, state.vb.slice()]; svg.setPointerCapture(e.pointerId); });
    svg.addEventListener('pointermove', (e) => {
      if (!drag) return;
      const r = svg.getBoundingClientRect();
      const s = Math.max(drag[2][2] / r.width, drag[2][3] / r.height);
      state.vb = [drag[2][0] - (e.clientX - drag[0]) * s, drag[2][1] - (e.clientY - drag[1]) * s, drag[2][2], drag[2][3]];
      svg.setAttribute('viewBox', state.vb.join(' '));
    });
    svg.addEventListener('pointerup', () => { drag = null; });
    new ResizeObserver(drawScale).observe(svg);

    // ---- side panel: checks, material, hardware, downloads ---------------------
    function side() {
      panel.innerHTML = '';
      const u = state.units;
      const g = doc.generator || {};
      panel.appendChild(h('div', 'lbl', `${doc.process} · ${g.name || ''} ${g.version || ''}`));
      if (doc.number) panel.appendChild(h('div', 'flatid', `${doc.number} v${doc.version}`));

      panel.appendChild(h('h4', null, 'Checks'));
      const cl = h('ul', 'flatchecks');
      for (const c of doc.checks || []) {
        const li = h('li', c.ok === true ? 'ok' : c.ok === false ? 'bad' : 'unk');
        li.appendChild(h('b', null, (c.ok === true ? '✓ ' : c.ok === false ? '✗ ' : '? ') + c.name));
        li.appendChild(h('div', 'dim', c.detail));
        cl.appendChild(li);
      }
      panel.appendChild(cl);

      panel.appendChild(h('h4', null, `Pieces (${doc.pieces.reduce((a, p) => a + p.qty, 0)})`));
      const pt = h('table', 'flattab');
      for (const p of doc.pieces) {
        const [, , w, hh] = bbox(p.cut);
        const tr = h('tr');
        // A piece that is its own plm part links to it: the assembly's BOM and
        // this table are the same list seen from two sides.
        const nameTd = h('td');
        if (p.part && p.part.number) {
          const a = h('a', null, p.name); a.href = itemPath(p.part.number);
          a.title = `${p.part.number} v${p.part.version}`;
          nameTd.append(a, h('div', 'dim', `${p.part.number} v${p.part.version}`));
        } else nameTd.textContent = p.name;
        tr.append(nameTd, h('td', 'num', '×' + p.qty), h('td', 'num', `${fmtLen(w, u)} × ${fmtLen(hh, u)}`));
        tr.onmouseenter = () => showPiece(p);
        pt.appendChild(tr);
      }
      panel.appendChild(pt);

      if (doc.nest && doc.nest.stock) {
        panel.appendChild(h('h4', null, 'Material'));
        const n = doc.nest;
        panel.appendChild(h('div', null, `${n.stock}`));
        panel.appendChild(h('div', 'big', `${n.yards.toFixed(2)} yd`));
        panel.appendChild(h('div', 'dim', `${fmtLen(n.length, u)} of ${fmtLen(n.stock_width, u)} roll${n.sheets ? ` · ${n.sheets} sheet(s)` : ''} — ${n.method}`));
      }
      if ((doc.bom || []).length) {
        panel.appendChild(h('h4', null, 'Hardware & notions'));
        const bt = h('table', 'flattab');
        for (const b of doc.bom) {
          const tr = h('tr');
          tr.append(h('td', null, b.item), h('td', 'num', `${b.qty} ${b.unit || ''}`));
          if (b.note) tr.title = b.note;
          bt.appendChild(tr);
        }
        panel.appendChild(bt);
      }
      // Downloads: the derivatives the document names, matched to real files on
      // this revision (never a guessed URL).
      const files = opts.files || [];
      const outs = doc.outputs || {};
      const labels = { pieces_pdf: 'Full-size pieces (PDF, 1:1)', tiled_pdf: `Tiled Letter (PDF${outs.tiled_pages ? ', ' + outs.tiled_pages + ' pp' : ''})`,
                       layout_pdf: 'Cutting layout (PDF)', dxf: 'DXF (cutter / CAM)', svg: 'SVG', report: 'Report' };
      const links = [];
      for (const [k, label] of Object.entries(labels)) {
        const name = outs[k];
        if (!name) continue;
        const f = files.find(x => (x.name || (x.path || '').split('/').pop()) === name);
        if (f && opts.urlFor) links.push([label, opts.urlFor(f), name]);
      }
      if (links.length) {
        panel.appendChild(h('h4', null, 'Print / cut'));
        const ul = h('ul', 'flatdl');
        for (const [label, url, name] of links) {
          const li = h('li'); const a = h('a', null, label);
          a.href = url; a.download = name; li.appendChild(a); ul.appendChild(li);
        }
        panel.appendChild(ul);
      }
    }

    draw();
    side();
  };
})();
